sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    toggleWhenToRun(newValue);
}

function toggleWhenToRun(value) {

    // BR related fields
    var brFields = [
        'business_rule',
    ];

    // Schedule related fields
    var scheduleFields = [
        'scheduled_job',
        'run_type',
        'time'
    ];

    // First hide everything
    hideFields(brFields);
    hideFields(scheduleFields);

    if (value == 'br') {
        showFields(brFields);
    }
    else if (value == 'schedule') {
        showFields(scheduleFields);
    }
    else {
        // nothing to show
    }
}

function hideFields(fields) {
    for (var i = 0; i < fields.length; i++) {
        if (g_form.hasField(fields[i])) {
            g_form.setMandatory(fields[i], false);
            g_form.setDisplay(fields[i], false);
        }
    }
}

function showFields(fields) {
    for (var i = 0; i < fields.length; i++) {
        if (g_form.hasField(fields[i])) {
            g_form.setDisplay(fields[i], true);
        }
    }
}
